/**
 * Compares two semantic version strings.
 * Returns -1 if a < b, 1 if a > b, and 0 if a === b.
 * 
 * @param {string} a
 * @param {string} b
 * @returns {number}
 */
export function compareSemver(a, b) {
  const v1 = a.split('.').map(Number);
  const v2 = b.split('.').map(Number);

  for (let i = 0; i < 3; i++) {
    const part1 = v1[i] || 0;
    const part2 = v2[i] || 0;

    if (part1 > part2) return 1;
    if (part1 < part2) return -1;
  }

  return 0;
}
