/**
 * Parses a single line of CSV data.
 * Handles fields enclosed in double quotes, including escaped quotes ("").
 * 
 * @param {string} line - The CSV line to parse.
 * @returns {string[]} - An array of fields.
 */
export function parseCsvLine(line) {
  const result = [];
  let currentField = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const nextChar = line[i + 1];

    if (inQuotes) {
      if (char === '"') {
        if (nextChar === '"') {
          // Escaped quote
          currentField += '"';
          i++;
        } else {
          // End of quoted field
          inQuotes = false;
        }
      } else {
        currentField += char;
      }
    } else {
      if (char === '"') {
        inQuotes = true;
      } else if (char === ',') {
        result.push(currentField);
        currentField = '';
      } else {
        currentField += char;
      }
    }
  }

  result.push(currentField);
  return result;
}
