/**
 * Groups items of an array into a Map based on a key.
 * 
 * @param {Array} items - The array of items to group.
 * @param {string|Function} key - The property name or a function to derive the key.
 * @returns {Map} A Map where keys are the group keys and values are arrays of items.
 */
export function groupBy(items, key) {
  const map = new Map();

  for (const item of items) {
    const groupKey = typeof key === 'function' ? key(item) : item[key];

    if (!map.has(groupKey)) {
      map.set(groupKey, []);
    }

    map.get(groupKey).push(item);
  }

  return map;
}
