/**
 * Converts an integer to a Roman numeral string.
 * @param {number} num 
 * @returns {string}
 */
export function toRoman(num) {
  const lookup = [
    ['M', 1000], ['CM', 900], ['D', 500], ['CD', 400],
    ['C', 100], ['XC', 90], ['L', 50], ['XL', 40],
    ['X', 10], ['IX', 9], ['V', 5], ['IV', 4], ['I', 1]
  ];
  let roman = '';
  for (const [symbol, value] of lookup) {
    while (num >= value) {
      roman += symbol;
      num -= value;
    }
  }
  return roman;
}

/**
 * Converts a Roman numeral string to an integer.
 * @param {string} str 
 * @returns {number}
 */
export function fromRoman(str) {
  const map = {
    'I': 1, 'V': 5, 'X': 10, 'L': 50,
    'C': 100, 'D': 500, 'M': 1000
  };
  let result = 0;
  for (let i = 0; i < str.length; i++) {
    const current = map[str[i]];
    const next = map[str[i + 1]];
    if (next > current) {
      result -= current;
    } else {
      result += current;
    }
  }
  return result;
}
