/**
 * A Least-Recently-Used (LRU) cache.
 * Uses a Map to maintain insertion order, which allows O(1) access
 * and O(1) updates for key-value pairs.
 */
export class LruCache {
  /**
   * @param {number} capacity
   */
  constructor(capacity) {
    this.capacity = capacity;
    this.cache = new Map();
  }

  /**
   * Returns the value associated with the key.
   * If the key exists, it is marked as most recently used.
   * @param {*} key
   * @returns {*} The value or undefined if not found.
   */
  get(key) {
    if (!this.cache.has(key)) {
      return undefined;
    }

    // Refresh the key by deleting and re-inserting it
    const value = this.cache.get(key);
    this.cache.delete(key);
    this.cache.set(key, value);
    return value;
  }

  /**
   * Sets a value in the cache. If the cache is at capacity,
   * the least recently used item is removed.
   * @param {*} key
   * @param {*} value
   */
  set(key, value) {
    if (this.cache.has(key)) {
      // Remove to update position
      this.cache.delete(key);
    } else if (this.cache.size >= this.capacity) {
      // Map.keys().next().value returns the first (oldest) key
      const oldestKey = this.cache.keys().next().value;
      this.cache.delete(oldestKey);
    }

    this.cache.set(key, value);
  }
}
