/**
 * Parses a duration string (e.g., "1h30m", "45s", "1d") into milliseconds.
 * Supported units: d (days), h (hours), m (minutes), s (seconds), ms (milliseconds).
 * 
 * @param {string} input
 * @returns {number}
 */
export function parseDuration(input) {
  const regex = /(\d+)(d|h|m|s|ms)/g;
  let totalMs = 0;
  let match;

  const units = {
    d: 24 * 60 * 60 * 1000,
    h: 60 * 60 * 1000,
    m: 60 * 1000,
    s: 1000,
    ms: 1
  };

  let found = false;
  while ((match = regex.exec(input)) !== null) {
    const value = parseInt(match[1], 10);
    const unit = match[2];

    if (units[unit]) {
      totalMs += value * units[unit];
      found = true;
    }
  }

  return found ? totalMs : 0;
}
