/**
 * Parses a URL query string into an object.
 * Handles multiple values for the same key by creating an array.
 * 
 * @param {string} query - The query string (e.g., "?a=1&b=2&a=3")
 * @returns {Object} - The parsed query object
 */
export function parseQuery(query) {
  const result = {};

  // Remove the leading '?' if present
  const queryString = query.startsWith('?') ? query.slice(1) : query;

  if (!queryString) {
    return result;
  }

  const pairs = queryString.split('&');

  for (const pair of pairs) {
    const [key, value] = pair.split('=');

    if (!key) continue;

    const decodedKey = decodeURIComponent(key);
    const decodedValue = value ? decodeURIComponent(value) : '';

    if (Object.prototype.hasOwnProperty.call(result, decodedKey)) {
      if (Array.isArray(result[decodedKey])) {
        result[decodedKey].push(decodedValue);
      } else {
        result[decodedKey] = [result[decodedKey], decodedValue];
      }
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
}
