/**
 * Wraps text into an array of strings, each with a maximum width.
 * Words are not broken unless a single word is longer than the width.
 * 
 * @param {string} text - The input text to wrap.
 * @param {number} width - The maximum character width per line.
 * @returns {string[]} - An array of wrapped lines.
 */
export function wrapText(text, width) {
  if (width <= 0) return [text];

  const words = text.split(' ');
  const lines = [];
  let currentLine = [];
  let currentLength = 0;

  for (const word of words) {
    // If adding the word exceeds width, push current line and start new one
    // (currentLength + 1 accounts for the space)
    if (currentLine.length > 0 && currentLength + 1 + word.length > width) {
      lines.push(currentLine.join(' '));
      currentLine = [];
      currentLength = 0;
    }

    // Handle case where a single word is longer than the width
    if (word.length > width) {
      // If we have content in currentLine, push it first
      if (currentLine.length > 0) {
        lines.push(currentLine.join(' '));
        currentLine = [];
        currentLength = 0;
      }
      // Break the long word itself
      let remaining = word;
      while (remaining.length > width) {
        lines.push(remaining.substring(0, width));
        remaining = remaining.substring(width);
      }
      currentLine.push(remaining);
      currentLength = remaining.length;
    } else {
      currentLine.push(word);
      currentLength += (currentLength === 0 ? word.length : word.length + 1);
    }
  }

  if (currentLine.length > 0) {
    lines.push(currentLine.join(' '));
  }

  return lines;
}
