/**
 * Wraps text to a specified width.
 * 
 * @param {string} text - The text to wrap.
 * @param {number} width - The maximum width of each line.
 * @returns {string[]} - An array of lines.
 */
export function wrapText(text, width) {
  if (width <= 0) return [text];

  const words = text.split(' ');
  const lines = [];
  let currentLine = [];
  let currentLength = 0;

  for (const word of words) {
    // If adding this word exceeds width, push current line and start new one
    // currentLength + word.length + (space if not first word)
    const space = currentLine.length > 0 ? 1 : 0;

    if (currentLength + space + word.length <= width) {
      currentLine.push(word);
      currentLength += space + word.length;
    } else {
      // If the line is not empty, save it
      if (currentLine.length > 0) {
        lines.push(currentLine.join(' '));
      }

      // Handle words longer than width by splitting them
      if (word.length > width) {
        let remainingWord = word;
        while (remainingWord.length > width) {
          lines.push(remainingWord.slice(0, width));
          remainingWord = remainingWord.slice(width);
        }
        currentLine = [remainingWord];
        currentLength = remainingWord.length;
      } else {
        currentLine = [word];
        currentLength = word.length;
      }
    }
  }

  if (currentLine.length > 0) {
    lines.push(currentLine.join(' '));
  }

