/**
 * Performs a deep equality check between two values.
 * 
 * @param {*} a
 * @param {*} b
 * @returns {boolean}
 */
export function deepEqual(a, b) {
  // Check for strict equality (handles primitives and same object references)
  if (a === b) {
    return true;
  }

  // If either is not an object or is null, they are not equal (since a !== b)
  if (
    typeof a !== 'object' || a === null ||
    typeof b !== 'object' || b === null
  ) {
    return false;
  }

  // Handle Arrays
  if (Array.isArray(a) !== Array.isArray(b)) {
    return false;
  }

  // Get keys for objects
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);

  // Check if number of keys match
  if (keysA.length !== keysB.length) {
    return false;
  }

  // Check if all keys in A exist in B and values are deeply equal
  for (const key of keysA) {
    if (!Object.prototype.hasOwnProperty.call(b, key) || !deepEqual(a[key], b[key])) {
      return false;
    }
  }

  return true;
}
