export function wrapText(text, width) {
  if (width <= 0) return [text];

  const words = text.split(' ');
  const lines = [];
  let currentLine = [];
  let currentLength = 0;

  for (const word of words) {
    // If a single word is longer than width, we must force-break it
    if (word.length > width) {
      // Push current line if it exists
      if (currentLine.length > 0) {
        lines.push(currentLine.join(' '));
        currentLine = [];
        currentLength = 0;
      }

      // Break the long word into chunks
      let remainingWord = word;
      while (remainingWord.length > width) {
        lines.push(remainingWord.substring(0, width));
        remainingWord = remainingWord.substring(width);
      }
      currentLine.push(remainingWord);
      currentLength = remainingWord.length;
    } else {
      // Check if adding this word (plus a space) exceeds width
      const spaceNeeded = currentLine.length > 0 ? 1 : 0;
      if (currentLength + spaceNeeded + word.length <= width) {
        currentLine.push(word);
        currentLength += spaceNeeded + word.length;
      } else {
        // Push current line and start a new one
        lines.push(currentLine.join(' '));
        currentLine = [word];
        currentLength = word.length;
      }
    }
  }

  if (currentLine.length > 0) {
    lines.push(currentLine.join(' '));
