/**
 * Merges overlapping intervals.
 * 
 * @param {number[][]} intervals - An array of [start, end] pairs.
 * @returns {number[][]} - The merged intervals.
 */
export function mergeIntervals(intervals) {
  if (intervals.length <= 1) {
    return intervals;
  }

  // 1. Sort intervals by start time
  const sorted = [...intervals].sort((a, b) => a[0] - b[0]);

  const merged = [sorted[0]];

  for (let i = 1; i < sorted.length; i++) {
    const current = sorted[i];
    const lastMerged = merged[merged.length - 1];

    // 2. If the current interval overlaps with the last merged interval,
    // merge them by updating the end time of the last merged interval.
    if (current[0] <= lastMerged[1]) {
      lastMerged[1] = Math.max(lastMerged[1], current[1]);
    } else {
      // 3. Otherwise, add the current interval to the result.
      merged.push(current);
    }
  }

  return merged;
}
