/**
 * A TokenBucket rate limiter that uses an explicit clock.
 */
export class TokenBucket {
  /**
   * @param {number} capacity - The maximum number of tokens the bucket can hold.
   * @param {number} fillRate - The number of tokens added per millisecond.
   */
  constructor(capacity, fillRate) {
    this.capacity = capacity;
    this.fillRate = fillRate;
    this.tokens = capacity;
    this.lastRefillTime = null;
  }

  /**
   * Attempts to consume a token.
   * @param {number} now - The current time in milliseconds.
   * @returns {boolean} - True if a token was consumed, false otherwise.
   */
  consume(now) {
    this._refill(now);

    if (this.tokens >= 1) {
      this.tokens -= 1;
      return true;
    }

    return false;
  }

  /**
   * Internal method to refill tokens based on elapsed time.
   * @param {number} now - The current time in milliseconds.
   */
  _refill(now) {
    if (this.lastRefillTime === null) {
      this.lastRefillTime = now;
      return;
    }

    const elapsed = now - this.lastRefillTime;
    if (elapsed > 0) {
      const tokensToAdd = elapsed * this.fillRate;
      this.tokens = Math.min(this.capacity, this.tokens + tokensToAdd);
      this.lastRefillTime = now;
    }
  }
}
