/**
 * Converts an integer to a Roman numeral string.
 * @param {number} num 
 * @returns {string}
 */
export function toRoman(num) {
  const map = [
    { val: 1000, sym: 'M' },
    { val: 900, sym: 'CM' },
    { val: 500, sym: 'D' },
    { val: 400, sym: 'CD' },
    { val: 100, sym: 'C' },
    { val: 90, sym: 'XC' },
    { val: 50, sym: 'L' },
    { val: 40, sym: 'XL' },
    { val: 10, sym: 'X' },
    { val: 9, sym: 'IX' },
    { val: 5, sym: 'V' },
    { val: 4, sym: 'IV' },
    { val: 1, sym: 'I' }
  ];

  let result = '';
  for (const entry of map) {
    while (num >= entry.val) {
      result += entry.sym;
      num -= entry.val;
    }
  }
  return result;
}

/**
 * Converts a Roman numeral string to an integer.
 * @param {string} str 
 * @returns {number}
 */
export function fromRoman(str) {
  const map = {
    'I': 1,
    'V': 5,
    'X': 10,
    'L': 50,
    'C': 100,
    'D': 500,
    'M': 1000
  };

  let result = 0;
  for (let i = 0; i < str.length; i++) {
    const current = map[str[i]];
    const next = map[str[i + 1]];

    if (next > current) {
      result -= current;
    } else {
      result += current;
    }
  }
  return result;
}
