/**
 * A Least-Recently-Used (LRU) cache implementation.
 * Uses a Map to maintain insertion order, which allows O(1) access
 * and O(1) updates for key-value pairs.
 */
export class LruCache {
  /**
   * @param {number} capacity The maximum number of items the cache can hold.
   */
  constructor(capacity) {
    this.capacity = capacity;
    this.cache = new Map();
  }

  /**
   * Retrieves a value from the cache.
   * If the key exists, it is marked as "most recently used" by
   * re-inserting it into the Map.
   * @param {*} key 
   * @returns {*} The value, or undefined if not found.
   */
  get(key) {
    if (!this.cache.has(key)) {
      return undefined;
    }

    // Refresh the key to mark it as most recently used
    const value = this.cache.get(key);
    this.cache.delete(key);
    this.cache.set(key, value);
    return value;
  }

  /**
   * Adds or updates a value in the cache.
   * If the cache exceeds capacity, the least recently used item (the first
   * item in the Map iterator) is removed.
   * @param {*} key 
   * @param {*} value 
   */
  put(key, value) {
    if (this.cache.has(key)) {
      // Remove existing to update order
      this.cache.delete(key);
    } else if (this.cache.size >= this.capacity) {
      // Map.keys().next().value returns the oldest key
      const oldestKey = this.cache.keys().next().value;
      this.cache.delete(oldestKey);
    }

    this.cache.set(key, value);
  }
}
